<?php
declare(strict_types=1);
namespace App\Modules\FreshFood\Controllers;
use App\Core\Auth;use App\Core\Authorization;use App\Core\Controller;use App\Modules\FreshFood\Services\FreshFoodCategoryService;use RuntimeException;use Throwable;
final class FreshFoodCategoryController extends Controller {private FreshFoodCategoryService $s;private Authorization $a;public function __construct(){$this->s=new FreshFoodCategoryService();$this->a=new Authorization();}private function allow(string $p,string $r='/fresh-food/categories'):bool{try{$this->a->authorize($p);return true;}catch(RuntimeException $e){flash('error',$e->getMessage());redirect($r);return false;}}public function index():void{if(!$this->allow('fresh_food.categories.view'))return;$t=(int)Auth::tenantId();$trash=($_GET['view']??'')==='trash';$this->view('FreshFood::Categories.index',['title'=>$trash?'Deleted Fresh Food Categories':'Fresh Food Categories','categories'=>$this->s->all($t,$trash),'trash'=>$trash]);}public function create():void{if(!$this->allow('fresh_food.categories.create'))return;$t=(int)Auth::tenantId();$this->view('FreshFood::Categories.create',['title'=>'Add Fresh Food Category','businesses'=>$this->s->restaurants($t)]);}public function store():void{if(!$this->allow('fresh_food.categories.create'))return;$t=(int)Auth::tenantId();try{$this->s->create($t,$_POST,(int)Auth::id());flash('success','Category created.');redirect('/fresh-food/categories');}catch(Throwable $e){$this->view('FreshFood::Categories.create',['title'=>'Add Fresh Food Category','businesses'=>$this->s->restaurants($t),'error'=>$e->getMessage(),'old'=>$_POST]);}}public function edit(int $id):void{if(!$this->allow('fresh_food.categories.edit'))return;$t=(int)Auth::tenantId();$r=$this->s->find($t,$id);if(!$r)abort(404);$this->view('FreshFood::Categories.edit',['title'=>'Edit Fresh Food Category','record'=>$r,'businesses'=>$this->s->restaurants($t)]);}public function update(int $id):void{if(!$this->allow('fresh_food.categories.edit'))return;$t=(int)Auth::tenantId();try{$this->s->update($t,$id,$_POST,(int)Auth::id());flash('success','Category updated.');redirect('/fresh-food/categories');}catch(Throwable $e){$this->view('FreshFood::Categories.edit',['title'=>'Edit Fresh Food Category','record'=>$_POST,'businesses'=>$this->s->restaurants($t),'error'=>$e->getMessage()]);}}public function destroy(int $id):void{if(!$this->allow('fresh_food.categories.delete'))return;try{$this->s->delete((int)Auth::tenantId(),$id,(int)Auth::id());flash('success','Category deleted.');}catch(Throwable $e){flash('error',$e->getMessage());}redirect('/fresh-food/categories');}public function restore(int $id):void{if(!$this->allow('fresh_food.categories.delete','/fresh-food/categories?view=trash'))return;try{$this->s->restore((int)Auth::tenantId(),$id,(int)Auth::id());flash('success','Category restored.');}catch(Throwable $e){flash('error',$e->getMessage());}redirect('/fresh-food/categories?view=trash');}}
